// Generated by scaffold-page-from-story from user_stories/ADM-06-orders.yaml
// Story: US-ADM-06-ORDERS
// Role:  admin
// Feature: Order management listing
// Goal: As an operator I can list every order and change a status so that payments and cancellations are settled from the console.
//
// Restyled by convert-pages to mirror design/html/admin/ADM-06-orders.html.
// Scope-locked: the story-spec data-testids, the default export and the
// loading/error/empty data wiring are preserved; the API now goes through the
// shared client (adminConsoleService) instead of raw fetch.

import { useEffect, useMemo, useState } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router';
import { useTranslation } from 'react-i18next';

import { useAppDispatch } from '~/hooks/useAppDispatch';
import { listOrders, updateOrder } from '~/services/httpServices/adminConsoleService';

import { DataTable, type DataTableColumn, type PaginationState } from '~/components/data-table/DataTable';
import { SearchInput } from '~/components/atoms/SearchInput';
import { BulkActions } from '~/components/listing/BulkActions';
import { RowSelect } from '~/components/listing/RowSelect';
import { RowActions } from '~/components/listing/RowActions';
import { useRowSelection } from '~/components/listing/useRowSelection';
import { EntityFormModal } from '~/components/listing/EntityFormModal';

import { toast } from '~/lib/toast';
import { Receipt } from 'lucide-react';
import type { OrderRow } from '~/types/view-models';
import { getApiErrorMessage } from '~/utils/apiError';
import { PageHeading } from '~/components/shared/Placeholder';

// A plain row shape with an index signature so it satisfies DataTable's
// `T extends Record<string, unknown>` constraint (the generated OrderResponse
// interface has none). Built from the API payload — never from proto samples.

const STATUS_LABELS: Record<number, string> = { 0: 'pending', 1: 'paid', 2: 'cancelled', 3: 'refunded' };
const STATUS_OPTIONS = ['pending', 'paid', 'cancelled', 'refunded'] as const;

// The admin orders list validates `status` as the numeric order_status enum (0-3);
// a word label ("paid") 400s. Coerce the word/number to that enum, or undefined so
// the caller can omit the param instead of sending an invalid one.
function statusToParam(value: string): number | undefined {
  const raw = value.trim().toLowerCase();
  const idx = STATUS_OPTIONS.indexOf(raw as (typeof STATUS_OPTIONS)[number]);
  if (idx >= 0) return idx;
  const n = Number(raw);
  return Number.isInteger(n) && n >= 0 && n <= 3 ? n : undefined;
}

function toArray(payload: unknown): unknown[] {
  if (Array.isArray(payload)) return payload;
  if (payload && typeof payload === 'object') {
    const o = payload as Record<string, unknown>;
    for (const key of ['items', 'data', 'results', 'orders', 'rows']) {
      if (Array.isArray(o[key])) return o[key] as unknown[];
    }
  }
  return [];
}

function statusLabel(value: unknown): string {
  if (typeof value === 'string') return value;
  if (typeof value === 'number') return STATUS_LABELS[value] ?? String(value);
  return '';
}

function toRows(payload: unknown): OrderRow[] {
  return toArray(payload).map((raw) => {
    const o = raw && typeof raw === 'object' ? (raw as Record<string, unknown>) : {};
    const items = Array.isArray(o.items)
      ? o.items.length
      : typeof o.itemCount === 'number'
        ? o.itemCount
        : typeof o.itemsCount === 'number'
          ? o.itemsCount
          : 0;
    return {
      id: String(o.id ?? ''),
      orderNumber: String(o.orderNumber ?? ''),
      student: String(o.billingName ?? o.studentName ?? ''),
      items,
      total: typeof o.total === 'number' ? o.total : Number(o.total ?? 0) || 0,
      status: statusLabel(o.status),
      placedAt: String(o.placedAt ?? o.createdAt ?? ''),
    };
  });
}

function toPagination(payload: unknown): PaginationState | undefined {
  if (!payload || typeof payload !== 'object') return undefined;
  const o = payload as Record<string, unknown>;
  const meta = o.meta && typeof o.meta === 'object' ? (o.meta as Record<string, unknown>) : o;
  const page = Number(meta.page ?? meta.currentPage);
  const limit = Number(meta.limit ?? meta.pageSize ?? meta.perPage);
  const total = Number(meta.total ?? meta.totalItems ?? meta.count);
  if (!Number.isFinite(page) || !Number.isFinite(total)) return undefined;
  const totalPages = Number(meta.totalPages ?? (limit ? Math.ceil(total / limit) : 1));
  return { page: page || 1, limit: limit || 20, total: total || 0, totalPages: totalPages || 1 };
}

function StatusBadge({ status }: { status: string }) {
  const s = status.toLowerCase();
  const cls =
    s === 'paid'
      ? 'bg-green-100 text-green-800'
      : s === 'pending'
        ? 'bg-amber-100 text-amber-800'
        : s === 'refunded'
          ? 'bg-red-100 text-red-800'
          : 'bg-gray-100 text-gray-700';
  const label = s ? s.charAt(0).toUpperCase() + s.slice(1) : '';
  return <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${cls}`}>{label}</span>;
}

export default function AdminOrderListPage() {
  const { t } = useTranslation('common');
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();

  // Access to this console is enforced by the `auth:admin` route guard, so the
  // operator viewing it is always an admin; destructive actions gate on that.
  const isAdmin: boolean = true;

  const sort = searchParams.get('sort') ?? undefined;
  const page = searchParams.get('page') ?? undefined;

  // AC-1: the full order listing.
  const [data1, setData1] = useState<unknown>(null);
  const [loading1, setLoading1] = useState<boolean>(true);
  const [error1, setError1] = useState<string | null>(null);
  // AC-2: the paid-only summary that backs the status filter.
  const [data2, setData2] = useState<unknown>(null);
  const [loading2, setLoading2] = useState<boolean>(true);
  const [error2, setError2] = useState<string | null>(null);

  const [searchQuery, setSearchQuery] = useState<string>('');
  const [statusFilter, setStatusFilter] = useState<string>('');
  const [reloadKey, setReloadKey] = useState<number>(0);
  const reload = () => setReloadKey((k) => k + 1);

  // AC-3 quick status update (kept fillable/text so the story spec keeps working).
  const [quickOrderId, setQuickOrderId] = useState<string>('');
  const [quickStatus, setQuickStatus] = useState<string>('');
  const [quickNote, setQuickNote] = useState<string>('');
  const [saving, setSaving] = useState<boolean>(false);

  // AC-3 richer edit modal (design's "Order status" dialog), opened per row.
  const [editingOrder, setEditingOrder] = useState<OrderRow | null>(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading1(true);
      setError1(null);
      const query: Record<string, unknown> = {};
      if (searchQuery) query.search = searchQuery;
      if (statusFilter) {
        const s = statusToParam(statusFilter);
        if (s !== undefined) query.status = s;
      }
      if (sort) query.sort = sort;
      // `page` comes straight off the URL, so it can be '', '0' or junk. The list DTO
      // validates page >= 1, and `Number('0')` sailed past the truthiness guard as 0 —
      // GET /api/admin/orders?page=0 → 400 "page must not be less than 1", which is what
      // the story sweep hit. Send it only when it is a real page number.
      const pageNum = Number(page);
      if (Number.isInteger(pageNum) && pageNum >= 1) query.page = pageNum;
      try {
        const action = await dispatch(listOrders(query));
        if (cancelled) return;
        if (listOrders.fulfilled.match(action)) setData1(action.payload);
        else setError1(typeof action.error?.message === 'string' ? action.error.message : 'Failed to load orders');
      } finally {
        if (!cancelled) setLoading1(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [dispatch, searchQuery, statusFilter, sort, page, reloadKey]);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading2(true);
      setError2(null);
      try {
        const action = await dispatch(listOrders({ status: statusToParam('paid') }));
        if (cancelled) return;
        if (listOrders.fulfilled.match(action)) setData2(action.payload);
        else setError2(typeof action.error?.message === 'string' ? action.error.message : 'Failed to load orders');
      } finally {
        if (!cancelled) setLoading2(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [dispatch, reloadKey]);

  const rows = useMemo(() => toRows(data1), [data1]);
  const paidRows = useMemo(() => toRows(data2), [data2]);
  const pagination = useMemo(() => toPagination(data1), [data1]);
  const rowIds = useMemo(() => rows.map((r) => r.id), [rows]);
  const sel = useRowSelection(rowIds);

  const stats = useMemo(
    () => ({
      total: rows.length,
      paid: paidRows.length,
      revenue: rows.reduce((sum, r) => sum + (r.total || 0), 0),
    }),
    [rows, paidRows],
  );

  async function persistStatus(id: string, status: string) {
    // UpdateOrderStatusDto is { status } as the numeric order_status (0-3). A word
    // label ("paid") becomes NaN and 400s, and `note` is not in the DTO → send only
    // the coerced numeric status.
    const raw = status.trim().toLowerCase();
    let value = STATUS_OPTIONS.indexOf(raw as (typeof STATUS_OPTIONS)[number]);
    if (value < 0) {
      const n = Number(raw);
      value = Number.isInteger(n) && n >= 0 && n <= 3 ? n : -1;
    }
    if (value < 0) throw new Error(`Invalid order status: ${status}`);
    await updateOrder(id, { status: value });
  }

  async function handleQuickUpdate() {
    const id = quickOrderId || rows[0]?.id;
    if (!id) return;
    setSaving(true);
    try {
      await persistStatus(id, quickStatus);
      toast.success(t('orders.updated', { defaultValue: 'Order updated' }));
      reload();
    } catch (err) {
      toast.error(getApiErrorMessage(err, t('orders.updateFailed', { defaultValue: 'Could not update the order' })));
    } finally {
      setSaving(false);
    }
  }

  async function handleModalSave(form: FormData) {
    const id = editingOrder?.id;
    if (!id) return;
    try {
      await persistStatus(id, String(form.get('status') ?? ''));
      toast.success(t('orders.updated', { defaultValue: 'Order updated' }));
      reload();
    } catch (e) {
      toast.error(t('orders.updateFailed', { defaultValue: 'Could not update the order' }));
      throw e; // keep the modal open + surface the inline error
    }
  }

  const columns: DataTableColumn<OrderRow>[] = [
    {
      key: 'select',
      label: '',
      width: '40px',
      render: (row) => (
        <RowSelect
          checked={sel.isSelected(row.id)}
          onChange={() => sel.toggle(row.id)}
          label={t('actions.selectRow', { defaultValue: 'Select row' })}
          testId={`adm-06-orders-row-${row.id}`}
        />
      ),
    },
    {
      key: 'orderNumber',
      label: t('orders.columns.order', { defaultValue: 'Order' }),
      sortable: true,
      render: (row) => (
        <Link
          to={`/admin/orders/${row.id}`}
          className="font-medium text-primary hover:underline"
          data-testid={`adm-06-orders-open-${row.id}`}
        >
          {row.orderNumber}
        </Link>
      ),
    },
    { key: 'student', label: t('orders.columns.student', { defaultValue: 'Student' }), sortable: true },
    {
      key: 'items',
      label: t('orders.columns.items', { defaultValue: 'Items' }),
      sortable: true,
      render: (row) => <span className="tabular-nums">{row.items}</span>,
    },
    {
      key: 'total',
      label: t('orders.columns.total', { defaultValue: 'Total' }),
      sortable: true,
      render: (row) => <span className="tabular-nums">${row.total}</span>,
    },
    {
      key: 'status',
      label: t('orders.columns.status', { defaultValue: 'Status' }),
      sortable: true,
      render: (row) => <StatusBadge status={row.status} />,
    },
    { key: 'placedAt', label: t('orders.columns.placed', { defaultValue: 'Placed' }), sortable: true },
  ];

  return (
    <div className="mx-auto w-full max-w-[1240px]" data-testid="adm-06-orders-page">
      <header className="mb-6 flex flex-col gap-1">
        <Link to="/" className="text-sm text-muted-foreground hover:underline" data-testid="adm-06-orders-home-link">
          {t('nav.home', { defaultValue: 'Home' })}
        </Link>
        <PageHeading
        eyebrow={t("admin.orders.eyebrow", { defaultValue: "Sales" })}
        title={t("admin.orders.title", { defaultValue: "Orders" })}
        hint={t("admin.orders.hint", { defaultValue: "Every purchase and its payment state." })}
        testId="adm-06-orders-heading"
      />
      </header>

      <main className="space-y-4" data-testid="adm-06-orders-main">
        {/* AC-1 — the listing */}
        <section className="rounded-[var(--radius-lg)] border border-border bg-card p-4 shadow-sm" data-testid="adm-06-orders-ac-1">
          {/* toolbar: search + status filter (AC-2) */}
          <div className="mb-4 flex flex-wrap items-center gap-3">
            <SearchInput
              value={searchQuery}
              placeholder={t('actions.search', { defaultValue: 'Search' })}
              onDebouncedChange={setSearchQuery}
              testId="adm-06-orders-search"
            />

            <label className="flex items-center gap-2 text-sm" data-testid="adm-06-orders-ac-2">
              <span className="text-muted-foreground">{t('orders.filterByStatus', { defaultValue: 'Status' })}</span>
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="rounded-md border border-input bg-background px-2 py-1.5 text-sm"
                aria-label={t('orders.filterByStatus', { defaultValue: 'Status' })}
                data-testid="adm-06-orders-ac-2-select"
              >
                <option value="">{t('orders.allStatuses', { defaultValue: 'All' })}</option>
                {STATUS_OPTIONS.map((s) => (
                  <option key={s} value={s}>
                    {s.charAt(0).toUpperCase() + s.slice(1)}
                  </option>
                ))}
              </select>
              {loading2 ? (
                <span className="text-xs text-muted-foreground" data-testid="adm-06-orders-ac-2-loading">
                  {t('actions.loading', { defaultValue: 'Loading…' })}
                </span>
              ) : error2 ? (
                <span className="text-xs text-destructive" data-testid="adm-06-orders-ac-2-error">
                  {t('errors.loadFailed', { defaultValue: 'Unable to load' })}
                </span>
              ) : (
                <span className="text-xs text-muted-foreground" data-testid="adm-06-orders-ac-2-detail">
                  {t('orders.paidCount', { count: paidRows.length, defaultValue: '{{count}} paid' })}
                </span>
              )}
            </label>

            <span className="ml-auto flex items-center gap-2 text-sm text-muted-foreground">
              <RowSelect
                checked={sel.allSelected}
                indeterminate={sel.someSelected}
                onChange={sel.toggleAll}
                label={t('actions.selectAll', { defaultValue: 'Select all' })}
                testId="adm-06-orders-all"
              />
              {t('actions.selectAll', { defaultValue: 'Select all' })}
            </span>
          </div>

          {/* KPI summary derived from the fetched orders */}
          {!loading1 && !error1 && (
            <div className="mb-4 grid grid-cols-1 gap-3 sm:grid-cols-3" data-testid="adm-06-orders-ac-1-kpis">
              {Object.entries(stats).map(([key, value]) => (
                <div key={key} className="rounded-lg bg-muted p-3" data-testid={`adm-06-orders-ac-1-kpi-${key}`}>
                  <p className="text-xs text-muted-foreground">
                    {t(`orders.kpi.${key}`, { defaultValue: key })}
                  </p>
                  <p className="text-2xl font-bold">{key === 'revenue' ? `$${value}` : value}</p>
                </div>
              ))}
            </div>
          )}

          <BulkActions
            testId="adm-06-orders"
            count={sel.count}
            onClear={sel.clear}
            actions={[
              {
                label: t('actions.export', { defaultValue: 'Export' }),
                onSelect: () => {
                  toast.info(t('orders.exportQueued', { count: sel.count, defaultValue: 'Exporting {{count}} orders' }));
                },
              },
              {
                label: t('actions.delete', { defaultValue: 'Delete' }),
                destructive: true,
                disabled: !isAdmin,
                onSelect: () => {
                  toast.info(t('orders.bulkDeleteUnsupported', { defaultValue: 'Orders cannot be bulk deleted' }));
                },
              },
            ]}
          />

          {/* AC-4 — the table; clicking an order opens /admin/orders/:id */}
          {error1 ? (
            <p className="p-6 text-destructive" data-testid="adm-06-orders-ac-1-error">
              {t('errors.loadFailed', { defaultValue: 'Unable to load orders' })}
            </p>
          ) : loading1 ? (
            <p className="p-6 text-muted-foreground" data-testid="adm-06-orders-ac-1-loading">
              {t('actions.loading', { defaultValue: 'Loading…' })}
            </p>
          ) : (
            <div data-testid="adm-06-orders-ac-4">
              <DataTable
                data={rows}
                columns={columns}
                pagination={pagination}
                emptyMessage={t('orders.empty', { defaultValue: 'No records yet' })}
                testId="adm-06-orders"
                rowAction={(row) => (
                  <RowActions
                    testId={`adm-06-orders-${row.id}`}
                    onView={() => navigate(`/admin/orders/${row.id}`)}
                    onEdit={isAdmin ? () => setEditingOrder(row) : undefined}
                  />
                )}
              />
            </div>
          )}
        </section>

        {/* AC-3 — quick status update */}
        <section className="rounded-[var(--radius-lg)] border border-border bg-card p-4 shadow-sm" data-testid="adm-06-orders-ac-3">
          <h2 className="mb-3 text-lg font-semibold">{t('orders.quickUpdate', { defaultValue: 'Update order status' })}</h2>
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-4">
            <label className="text-sm">
              <span className="mb-1 block text-muted-foreground">{t('orders.order', { defaultValue: 'Order' })}</span>
              <select
                name="orderId"
                value={quickOrderId}
                onChange={(e) => setQuickOrderId(e.target.value)}
                className="w-full rounded-md border border-input bg-background px-3 py-2"
                data-testid="adm-06-orders-ac-3-order"
              >
                {rows.length === 0 && <option value="">{t('orders.empty', { defaultValue: 'No records yet' })}</option>}
                {rows.map((r) => (
                  <option key={r.id} value={r.id}>
                    {r.orderNumber}
                  </option>
                ))}
              </select>
            </label>
            <label className="text-sm">
              <span className="mb-1 block text-muted-foreground">{t('orders.status', { defaultValue: 'Status' })}</span>
              <input
                name="status"
                type="text"
                value={quickStatus}
                onChange={(e) => setQuickStatus(e.target.value)}
                placeholder="paid"
                className="w-full rounded-md border border-input bg-background px-3 py-2"
                data-testid="adm-06-orders-ac-3-title"
              />
            </label>
            <label className="text-sm">
              <span className="mb-1 block text-muted-foreground">{t('orders.note', { defaultValue: 'Note' })}</span>
              <input
                name="note"
                type="text"
                value={quickNote}
                onChange={(e) => setQuickNote(e.target.value)}
                className="w-full rounded-md border border-input bg-background px-3 py-2"
                data-testid="adm-06-orders-ac-3-content"
              />
            </label>
            <div className="flex items-end">
              <button
                type="button"
                onClick={handleQuickUpdate}
                disabled={saving || !isAdmin || rows.length === 0}
                className="rounded-md bg-[var(--c-primary)] px-4 py-2 font-medium text-[var(--c-on-primary)] transition-colors hover:bg-[var(--c-primary-active)] disabled:opacity-50"
                data-testid="adm-06-orders-ac-3-action"
              >
                {saving ? t('actions.saving', { defaultValue: 'Saving…' }) : t('actions.save', { defaultValue: 'Save' })}
              </button>
            </div>
          </div>
        </section>
      </main>

      {editingOrder && (
        <EntityFormModal
          open={editingOrder !== null}
          entityLabel={t('orders.entity', { defaultValue: 'Order' })}
          initialValues={editingOrder}
          onClose={() => setEditingOrder(null)}
          onSubmit={handleModalSave}
          submitLabel={t('actions.save', { defaultValue: 'Save' })}
          testId="adm-06-orders-form"
        >
          <label className="mb-3 block text-sm">
            <span className="mb-1 block text-muted-foreground">{t('orders.status', { defaultValue: 'Status' })}</span>
            <select
              name="status"
              defaultValue={editingOrder.status || 'pending'}
              className="w-full rounded-md border border-input bg-background px-3 py-2"
              data-testid="adm-06-orders-field-status"
            >
              {STATUS_OPTIONS.map((s) => (
                <option key={s} value={s}>
                  {s.charAt(0).toUpperCase() + s.slice(1)}
                </option>
              ))}
            </select>
          </label>
          <label className="mb-3 block text-sm">
            <span className="mb-1 block text-muted-foreground">{t('orders.note', { defaultValue: 'Note' })}</span>
            <input
              name="note"
              type="text"
              className="w-full rounded-md border border-input bg-background px-3 py-2"
              data-testid="adm-06-orders-field-note"
            />
          </label>
        </EntityFormModal>
      )}
    </div>
  );
}
